  'Add time': 'إضافة وقت',
  'Targets stay where you set them.': 'تبقى الأهداف كما حددتها.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'أكمل كل تكرار في كل مجموعة ويرتفع الوزن. وعدم إكمال التكرارات عدة مرات يؤدي إلى تخفيف الحمل.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'مجموعتان عاديتان، ثم مجموعة أخيرة حتى الفشل. إذا تجاوزت الهدف في تلك المجموعة يزداد الوزن (والزيادة مضاعفة إذا ضاعفت التكرارات). وعند الفشل مرة واحدة يُخفَّض الوزن بنسبة 10%.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'تدرج عبر نطاق تكرارات بنفس الوزن. بلغ قمة النطاق في كل مجموعة ويرتفع الوزن، وتعود التكرارات إلى الأسفل.',
  'Hold every set for the full duration and the target goes up.': 'ثبّت كل مجموعة للمدة الكاملة ويرتفع الهدف.',
  'Nothing logged yet, so this session sets the baseline.': 'لم يُسجَّل شيء بعد، لذا تحدد هذه الجلسة خط الأساس.',
  'Held every set for the full time. Target goes up by {0}s.': 'ثبّت كل مجموعة للوقت الكامل. الهدف يرتفع بمقدار {0}ث.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '{0} جلسات قصيرة متتالية. تراجع إلى {1}ث ثم ابنِ من جديد.',
  'Came up short last time. Same target again.': 'لم تبلغ المدة الكاملة في المرة السابقة. نفس الهدف مجددًا.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'بلغت قمة نطاق التكرارات في كل مجموعة. زيادة {0} {1} والعودة إلى {2} تكرارات.',
  'Stuck for {0} sessions. Deload to {1} {2}.': 'تعثّر التقدم {0} جلسات. خفّف الحمل إلى {1} {2}.',
  'Same weight, aim for {0} reps this time.': 'نفس الوزن، استهدف {0} تكرارات هذه المرة.',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': 'بلغت المجموعة الأخيرة {0} تكرارات، ضعف الهدف! ارفع الوزن قفزة مزدوجة بمقدار {1} {2}.',
  'Every rep last time. {0} {1} more.': 'كل التكرارات في المرة السابقة. زيادة {0} {1}.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'تكرارات ناقصة في {0} جلسات متتالية. خفّض الوزن إلى {1} {2} ثم عاود التدرّج.',
  'Missed reps. Reset to {0} {1} and work back up.': 'تكرارات ناقصة. خفّض الوزن إلى {0} {1} ثم عاود التدرّج.',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'تكرارات ناقصة في المرة السابقة. نفس الوزن مجددًا ({0} من {1} متبقٍ).',
  'Bodyweight: every rep last time, so go for {0} this time.': 'وزن الجسم: كل التكرارات في المرة السابقة، لذا استهدف {0} هذه المرة.',
  'Bodyweight: same target again until every set is clean.': 'وزن الجسم: نفس الهدف مجددًا حتى تكتمل كل المجموعات بنظافة.',
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0} مجموعات تحمل معها {1}. فعّل «الجهد لكل مجموعة» في الإعدادات لعرضها.',
  '{0} sets bring an {1} with them.': '{0} مجموعات تحمل معها {1}.',
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': 'الجهد لكل مجموعة',
  'What are RIR and RPE?': 'ما هما RIR وRPE؟',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': 'مدى صعوبة المجموعة، يُسجَّل بجانب الوزن والتكرارات. مقياسان لنفس التقييم، يُحسبان من طرفين متقابلين.',
  'How it felt': 'كيف كان مستوى الجهد؟',
  'Nothing left, went to failure': 'لا شيء متبقٍ، وصلت إلى الفشل',
  'One more rep in the tank': 'تكرار واحد في الاحتياط',
  'Two more reps': 'تكراران في الاحتياط',
  'Three more reps': 'ثلاثة تكرارات في الاحتياط',
  'Easy, warm-up territory': 'سهل، في نطاق الإحماء',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'يعدّ RIR التكرارات التي تركتها في الخزان؛ بينما يقيس RPE الجهد نفسه على مقياس من 10، إذن RPE ≈ 10 − RIR. اختر المقياس الذي تفكر به أصلًا.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'الصف المميز هو حيث تقع معظم مجموعات العمل. المجموعات المسجلة سابقًا تحتفظ بمقياسها الخاص، ولا شيء آخر يقرأ هذه القيمة، لذا لا يتأثر التدرّج ولا 1RM التقديري.',
