  'Where the sets land': 'أين تقع المجموعات',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'معظم مجموعات العمل مكانها قرب الفشل، لا عنده. نصف عند الأدنى ونصف عند الأعلى يعطيان متوسطًا يبدو صحيًا رغم ذلك.',
  'Average effort per workout': 'متوسط الجهد لكل تمرين',
  'A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.': 'النقطة الأكثر امتلاءً تعني أن ما تبقى في الخزان أقل. نفس الوزن عند {0} أقل تقدّم لا يُظهره الخط وحده.',
