  'For dips or pull-ups with a belt. Progression then follows the weight.': 'لتمارين الغطس أو العقلة مع حزام. عندها يعتمد التدرج على الوزن.',
  'For lunges, single-arm rows and the like.': 'لتمارين الاندفاع والسحب بذراع واحدة وما يشابهها.',
  'Top of the range': 'قمة النطاق',
  'Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.': 'تزداد التكرارات بمقدار واحد عندما تكمل جميع المجموعات بالشكل المطلوب. حدد سقفًا تتحول عنده الزيادة إلى إضافة مجموعات بدلًا من التكرارات.',
  'Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.': 'ترتفع التكرارات إلى {0}، ثم تُضاف مجموعة وتبدأ التكرارات من جديد. عند {1} مجموعات يطلب منك إضافة وزن بدلًا من ذلك.',
