  'Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.': 'الوضع المحلي يحفظ كل شيء على هذا الهاتف. أما الاتصال فيزامن بياناتك مع خادم openGym الخاص بك. يمكنك التبديل لاحقًا من الإعدادات.',
