  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'يبقى اسمك وتفاصيل تسجيل دخولك وكل ما يخص حسابك هنا. لا تُضمَّن بيانات الآخرين أبدًا.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'المدرب ليس طبيبًا ولا أخصائي علاج طبيعي. إذا كان هناك ألم، استشر مختصًا.',
