  'Anything to work around?': 'أي شيء يجب تجنبه؟',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'إصابات، مفاصل تؤلمك، حركات لا تستطيع أداءها، أو قيود عملية مثل التدريب في السادسة صباحًا داخل شقة.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'مثلًا «كتف أيسر مُتعِب، لا ضغط بار فوق الرأس»',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'إذا كان هناك ألم حقيقي، استشر مختصًا. سيبرمج المدرب بحذر، لكنه لا يستطيع تشخيص أي شيء.',
