  'The Coach is already thinking about your training.': 'المدرب يفكر بالفعل في تدريبك.',
  'The Coach is taking a breather. You’ve used today’s {0} runs on this phone.': 'المدرب يلتقط أنفاسه. استخدمت تشغيلات اليوم البالغة {0} على هذا الهاتف.',
  'The Coach isn’t set up on this phone.': 'المدرب غير معد على هذا الهاتف.',
