  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': 'يُخزن المفتاح في التخزين الآمن لهذا الهاتف ولا يغادره إلا لاستدعاء المزود.',
  'This phone calls the provider directly with your key. Every request is charged to your account.': 'يتصل هذا الهاتف بالمزود مباشرة بمفتاحك. يُحاسب حسابك على كل طلب.',
  'Turn the Coach off on this phone': 'إيقاف المدرب على هذا الهاتف',
  'Use my self-hosted openGym': 'استخدام openGym المستضاف ذاتيًا',
  'What leaves this phone': 'ما يغادر هذا الهاتف',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'خادمك لا يفعّل المدرب. اسأل مشرفه، أو استخدم مفتاحك الخاص أدناه.',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'يشغّل خادمك المدرب بالمزود الذي أعده مشرفه. لا يغادر هذا الهاتف شيء جديد أبعد مما تتم مزامنته بالفعل.',
  'Loading the exercise catalogue…': 'جارٍ تحميل كتالوج التمارين…',
