  'A local model can take longer.': 'قد يستغرق النموذج المحلي وقتًا أطول.',
  'All optional. The more the Coach knows, the less it guesses.': 'كلها اختيارية. كلما عرف المدرب أكثر، قلّ تخمينه.',
  'Almost there': 'أوشكنا على الانتهاء',
  'Avoid: {0}': 'تجنّب: {0}',
  'Before we start': 'قبل أن نبدأ',
  'Building your plan…': 'جارٍ بناء خطتك…',
  'Discarded. Tell me what was off and I will build a different one.': 'تم التجاهل. أخبرني بما كان غير مناسب وسأبني خطة مختلفة.',
  'Done! Your plan is back to how it was before my last changes.': 'تم! عادت خطتك إلى ما كانت عليه قبل آخر تغييراتي.',
  'Edit my answers': 'تعديل إجاباتي',
  'Experience': 'الخبرة',
  'Goal, days, equipment, limits': 'الهدف والأيام والمعدات والقيود',
  'Have a look at my training and tell me what you would change.': 'ألقِ نظرة على تدريبي وأخبرني بما كنت ستغيّره.',
  'Here is what I am working with:': 'إليك ما أعمل به:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'مرحبًا، أنا مدربك. أبني خطتك من إجاباتك وأعدّلها بناءً على ما تسجله فعلًا. لا يتغير شيء حتى توافق.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'اطّلعت على كل شيء ولا يوجد ما أغيّره الآن. استمر هكذا، واسألني مجددًا بعد بضع جلسات أخرى.',
  'I understand, let’s go': 'فهمت، هيا بنا',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'تم الاستيراد! {0} روتينات في خطتك وأسبوعك مضبوط. أراك في الجلسة القادمة.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'تم الاستيراد! {0} روتينات في خطتك. أسبوعك لم يتغير؛ جدولها متى شئت.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'يصمم خطتك من بضعة إجابات ويعدّلها بناءً على ما تسجله فعلًا. لا يغيّر شيئًا دون موافقتك، ويمكنك التراجع عن كل تغيير.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'الروتينات والتمارين والمجموعات والتكرارات، وجدولك الأسبوعي وإعدادات التقدم.',
  'Your logged training': 'تدريبك المسجل',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'المجموعات التي سجلتها خلال فترة المراجعة: الأوزان والتكرارات والأوقات وتقييمات الجهد ومدة الجلسات، وملاحظات جلساتك.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'قياسات الوزن من الفترة نفسها، ووزنك المستهدف إن كنت قد حددته.',
  'What you tell the Coach': 'ما تخبر به المدرب',
  'Your intake answers, including any limitations or injuries you describe.': 'إجاباتك على أسئلة البداية، بما في ذلك أي قيود أو إصابات تصفها.',
  'A few preferences': 'بعض التفضيلات',
  'Your unit, your language and which effort scale you log.': 'وحدتك ولغتك ومقياس الجهد الذي تسجل به.',
  'Likes: {0}': 'المفضلات: {0}',
  'Limits': 'القيود',
  'Limits: {0}': 'القيود: {0}',
  'Not quite right? Say what to change below and I will revise the whole plan.': 'ليست مناسبة تمامًا؟ اذكر ما تريد تغييره أدناه وسأراجع الخطة كاملة.',
  'Pick one to continue.': 'اختر واحدًا للمتابعة.',
  'Pick what you will actually keep, not the best week you can imagine.': 'اختر ما ستلتزم به فعلًا، لا أفضل أسبوع يمكنك تخيله.',
  'Reading your training…': 'جارٍ قراءة تدريبك…',
