  'Sent straight to {0} with your own API key. You pay for every request.': 'يُرسل مباشرة إلى {0} بمفتاح API الخاص بك. تدفع مقابل كل طلب.',
  'Sent to {0}, running on this server under the instance owner’s account.': 'يُرسل إلى {0}، الذي يعمل على هذا الخادم تحت حساب مالك المثيل.',
  'Session length': 'مدة الجلسة',
  'Sets the pace of progression, and how much the Coach assumes you know.': 'يحدد وتيرة التقدم، ومدى ما يفترضه المدرب من معرفتك.',
