  'Reset your password': 'إعادة تعيين كلمة المرور',
  'Enter the code your admin gave you and choose a new password. It signs you out everywhere else.': 'أدخل الرمز الذي أعطاك إياه المسؤول واختر كلمة مرور جديدة. سيُسجَّل خروجك من كل مكان آخر.',
  'Reset code': 'رمز إعادة التعيين',
