  'This folder can’t be used for backups.': 'لا يمكن استخدام هذا المجلد للنسخ الاحتياطية.',
  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'لم يعد بإمكان openGym الكتابة في «{0}»، لذا تُحفظ النسخ في Documents/openGym من جديد. اختر المجلد مرة أخرى للعودة إليه.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'لم يعد بإمكان openGym الكتابة في المجلد المختار، لذا تُحفظ النسخ في Documents/openGym من جديد. اختر المجلد مرة أخرى للعودة إليه.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'نبّهني عندما أفوّت تمرينًا مخططًا',
  'Nudge tone': 'نبرة التنبيه',
  'Friendly': 'ودود',
  'Guilt trip': 'تأنيب الضمير',
  'Drill sergeant': 'رقيب التدريب',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'تنبيه واحد مساء يوم مخطط لم يُسجَّل فيه شيء، بين 20:00 و21:30. بعد 3 أيام فائتة متتالية يصمت حتى تمرينك التالي.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': 'سجّلت تمرينًا على جهاز آخر؟ قبل التنبيه يتحقق الهاتف من خادمك، متى سمح للتطبيق بالعمل في الخلفية. فتح التطبيق يحدّث كل شيء دائمًا.',
  'Everything okay?': 'هل كل شيء على ما يرام؟',
  '{0} is still waiting. What’s up?': '{0} ما زال ينتظرك. ما الأمر؟',
  'No {0} today? Even a short session tomorrow counts.': 'لا {0} اليوم؟ حتى جلسة قصيرة غدًا تُحسب.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'يوم صعب؟ {0} يمكنه الانتظار. غدًا بداية جديدة.',
  'Hey, {0} didn’t happen today. All good?': 'مرحبًا، لم يحدث {0} اليوم. هل كل شيء بخير؟',
  'I miss you': 'اشتقت إليك',
  '{0} waited by the door all evening. For you.': '{0} انتظرك عند الباب طوال المساء. أنت بالذات.',
  'The barbell asked about you today. I didn’t know what to say.': 'سأل عنك البار اليوم. لم أعرف ماذا أقول.',
  'Was it something I said? {0} misses you.': 'هل قلت شيئًا أزعجك؟ {0} مشتاق إليك.',
  'I saved you a spot on the bench. It’s still empty.': 'حجزت لك مكانًا على المقعد. ما زال فارغًا.',
  'Attention, recruit!': 'انتباه أيها المجنّد!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'مكاسبك تحزم حقائبها. {0} غدًا، بلا أعذار!',
  '{0} doesn’t do itself, recruit. Move it!': '{0} لن ينجز نفسه أيها المجنّد. تحرّك!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'الأعذار لا ترفع الأوزان. احضر غدًا إلى {0}!',
  'Your muscles filed a missing-person report. Show up for {0}!': 'عضلاتك أبلغت عن فقدانك. احضر إلى {0}!',
  'That address answers, but it isn’t an openGym server. Check the URL.': 'هذا العنوان يستجيب، لكنه ليس خادم openGym. تحقّق من الرابط.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'هذا العنوان يستجيب، لكن صفحة تسجيل دخول أو قاعدة في البروكسي ردّت بدلًا من openGym. اترك /api/ يصل إلى openGym دون تغيير. راجع “Phone app and CORS” في docs/SELF_HOSTING.md.',
  'Switch sides': 'بدّل الجهة',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'يحفظ نسخة مؤرّخة في «{0}» بعد إنهاء تمرين أو تعديل روتين، ويحتفظ بأحدث {1}.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'يحفظ نسخة مؤرّخة في المجلد الذي اخترته بعد إنهاء تمرين أو تعديل روتين، ويحتفظ بأحدث {0}.',
  // --- Plan: Schedule | Routines (v1.3.11) ---
  'Plan options': 'خيارات الخطة',
  'Your routines in a loop': 'روتيناتك في دورة متكررة',
  'Back to a fixed week?': 'العودة إلى أسبوع ثابت؟',
  'The loop stops. Your weekdays stay as they are, and the loop is saved for later.': 'تتوقف الدورة. تبقى أيام أسبوعك كما هي، وتُحفظ الدورة لوقت لاحق.',
  'Routines in a loop. Whatever is next stays next until you train it, whatever the day.': 'روتينات في دورة متكررة. يبقى التالي هو التالي حتى تتمرنه، أيًا كان اليوم.',
  'The same routines on the same weekdays, every week.': 'الروتينات نفسها في الأيام نفسها، كل أسبوع.',
  'How you train': 'طريقة تمرينك',
  'Want two routines on one day? Tap the day and pick both.': 'روتينان في يوم واحد؟ اضغط على اليوم واختر الاثنين.',
  'The loop': 'الدورة',
  '{0} of {1} done this round.': 'تم {0} من {1} في هذه الجولة.',
  'Drag to reorder. Tap the minus to take one out.': 'اسحب لإعادة الترتيب. اضغط علامة الناقص لإزالة واحد.',
  'Trained out of order? Just pick another routine on Home.': 'تمرنت بغير الترتيب؟ فقط اختر روتينًا آخر في الرئيسية.',
  'Start the loop over': 'ابدأ الدورة من جديد',
  'Start the loop': 'ابدأ الدورة',
  'Also on fixed days': 'أيضًا في أيام ثابتة',
  'These count on top of the loop. Tap a day to change or clear it.': 'تُحسب هذه إضافة إلى الدورة. اضغط على يوم لتغييره أو إفراغه.',
  'Now in Stats, next to Muscle balance': 'الآن في الإحصائيات، بجانب توازن العضلات',
  'Tap to plan something': 'اضغط لتخطيط شيء',
  'Drag to reorder': 'اسحب لإعادة الترتيب',
  'Drag to reorder. Tap the minus to delete.': 'اسحب لإعادة الترتيب. اضغط علامة الناقص للحذف.',
  'Tap a routine to edit it. Reorder and delete are behind Edit.': 'اضغط على روتين لتعديله. إعادة الترتيب والحذف ضمن تعديل.',
