  'That file isn’t an openGym backup.': 'هذا الملف ليس نسخة احتياطية من openGym.',
  'That zip was repacked. Import the original backup file.': 'أُعيد ضغط ملف zip هذا. استورد ملف النسخة الاحتياطية الأصلي.',
