  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': 'للرد، يرسل المدرب هذه البيانات عبر خادم openGym الخاص بك إلى {0}، وهي خدمة ذكاء اصطناعي خارج openGym اختارها مسؤول خادمك:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'للرد، يرسل هذا الجهاز هذه البيانات مباشرة إلى {0}، وهي خدمة ذكاء اصطناعي خارج openGym، باستخدام مفتاح API الخاص بك:',
  'Who may see your training': 'من يمكنه رؤية تمارينك',
  'Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.': 'الجهات التي يمكن للمدرب إرسال تمارينك إليها من هذا الجهاز. إذا سحبت الإذن، يسألك المدرب مجددًا في المرة القادمة. النموذج على شبكتك الخاصة لا يحتاج إلى إذن أبدًا.',
  'With your API key': 'باستخدام مفتاح API الخاص بك',
  'Withdraw': 'سحب الإذن',
  'Withdrawn. The Coach will ask before it sends anything again.': 'تم سحب الإذن. سيسألك المدرب قبل أن يرسل أي شيء مجددًا.',
  'Your answers to the Coach: goal, days, equipment, limits and injuries': 'إجاباتك للمدرب: الهدف والأيام والمعدات والقيود والإصابات',
  'Your body weight and goal weight': 'وزنك ووزنك المستهدف',
  'Your data, your call': 'بياناتك، قرارك',
  'Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.': 'اسمك وبريدك الإلكتروني وتسجيل دخولك تبقى هنا. تتعامل {0} مع الباقي وفق قواعد الخصوصية الخاصة بها.',
  'Your plan: routines, exercises, sets, reps and schedule': 'خطتك: الروتينات والتمارين والمجموعات والتكرارات والجدول',
  'Your unit and language': 'وحدتك ولغتك',
  'Your workouts: weights, reps, times, effort and session notes': 'تمارينك: الأوزان والتكرارات والأوقات والجهد وملاحظات الجلسة',
  // --- delete my account (App Store rule 5.1.1(v)) ---
  'Delete my account': 'حذف حسابي',
  'Removes your profile and everything in it from this server.': 'يزيل ملفك الشخصي وكل ما فيه من هذا الخادم.',
  'Delete your account?': 'حذف حسابك؟',
  'Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.': 'سيُحذف ملفك الشخصي وتدريباتك ووزن جسمك وصورك ومقاطع الفيديو من هذا الخادم نهائيًا. لا تراجع، ولا حتى المسؤول يستطيع استعادتها.',
  'Want a copy first? Export a backup. You can import it into openGym anytime.': 'تريد نسخة أولًا؟ صدّر نسخة احتياطية. يمكنك استيرادها إلى openGym في أي وقت.',
  'Type {0} to confirm.': 'اكتب {0} للتأكيد.',
  'Account name': 'اسم الحساب',
  'Delete forever': 'حذف نهائي',
  'That is not your account name.': 'هذا ليس اسم حسابك.',
  'You’re the only admin here, and other profiles still use this server. Make someone else an admin first.': 'أنت المسؤول الوحيد هنا، وملفات أخرى ما زالت تستخدم هذا الخادم. اجعل شخصًا آخر مسؤولًا أولًا.',
  'Couldn’t delete the account. Nothing was removed.': 'تعذّر حذف الحساب. لم يُحذف أي شيء.',
  'Your account is gone. Thanks for every rep.': 'حسابك لم يعد موجودًا. شكرًا على كل تكرار.',
  'Confirm it’s you to delete your openGym account': 'أكّد أنك أنت لحذف حساب openGym',
  'Not confirmed on this phone. Nothing was deleted.': 'لم يتم التأكيد على هذا الهاتف. لم يُحذف أي شيء.',
  'This phone has no screen lock, so the name you typed is the only check.': 'لا يوجد قفل شاشة على هذا الهاتف، لذا فالاسم الذي كتبته هو التحقق الوحيد.',
  'Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.': 'سيتحقق هاتفك من أنك أنت (الوجه أو البصمة أو رمز المرور)، ثم يُحذف الحساب.',
  // --- first-start permission steps ---
  'Never miss the end of a rest': 'لا تفوّت نهاية الراحة أبدًا',
  'One quick thing': 'شيء سريع واحد',
  'Rest timer, right on the lock screen': 'مؤقت الراحة مباشرة على شاشة القفل',
  'Training reminders, only if you switch them on': 'تذكيرات التمرين، فقط إذا فعّلتها',
  'You can change it anytime in your phone’s settings.': 'يمكنك تغيير ذلك في أي وقت من إعدادات هاتفك.',
  'openGym can tap you on the shoulder when a rest is over, even with the phone locked in your pocket.': 'يمكن لـ openGym أن ينقر على كتفك عند انتهاء الراحة، حتى والهاتف مقفل في جيبك.',
