  '%1RM for {0}': '%1RM لـ {0}',
  '%1RM per lift': '%1RM لكل تمرين',
  'Again, a bit heavier': 'مرة أخرى، أثقل قليلًا',
  'Back to my plan': 'العودة إلى خطتي',
  'Delete programme': 'حذف البرنامج',
  'Deload week': 'أسبوع تفريغ',
  'Each adds its own routines, so your plan stays as it is until you start it.': 'كل واحد يضيف روتيناته الخاصة، فتبقى خطتك كما هي حتى تبدأه.',
  'Effort for the week': 'مجهود الأسبوع',
  'Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.': 'تركه فارغًا يترك الوزن للتدرّج. يُحسب %1RM من أفضل 1RM تقديري لديك.',
  'End programme': 'إنهاء البرنامج',
  'End “{0}”?': 'إنهاء "{0}"؟',
  'Four days. Your progression picks the weights, the effort climbs to RPE 9, then a deload.': 'أربعة أيام. التدرّج يختار الأوزان، والمجهود يرتفع حتى RPE 9، ثم تفريغ.',
  'Heavier means every %1RM goes up {0} points.': 'أثقل يعني أن كل %1RM يرتفع {0} نقطة.',
  'It is running: ending it brings your plan back. Its routines stay.': 'إنه قيد التشغيل: إنهاؤه يعيد خطتك. روتيناته تبقى.',
  'Its routines stay.': 'روتيناته تبقى.',
  'Its schedule takes over your plan until you end it. Then your plan comes back as it was.': 'جدوله يحل محل خطتك حتى تنهيه. بعدها تعود خطتك كما كانت.',
  'Lighter weights, and its sessions do not count toward progression.': 'أوزان أخف، وجلساته لا تُحتسب في التدرّج.',
