  'No programmes yet. Make one from your plan, or grab a starter below.': 'لا توجد برامج بعد. أنشئ واحدًا من خطتك، أو اختر برنامج بداية بالأسفل.',
  'No schedule yet. Put routines on your week or in a loop in Plan, then take it over here.': 'لا يوجد جدول بعد. ضع روتينات على أسبوعك أو في تناوب في الخطة، ثم انقله إلى هنا.',
  'Nothing set, progression as usual': 'لا شيء محدد، التدرّج كالمعتاد',
