  'The schedule in your plan right now becomes this programme’s.': 'الجدول الموجود في خطتك الآن يصبح جدول هذا البرنامج.',
  'The week is the calendar week: week 1 is the one you start in. A pause holds it.': 'الأسبوع هو أسبوع التقويم: الأسبوع 1 هو الذي تبدأ فيه. الإيقاف المؤقت يثبّته.',
  'This programme is gone.': 'هذا البرنامج لم يعد موجودًا.',
  'Three days of plain linear progression, with a deload every fourth week.': 'ثلاثة أيام من التدرّج الخطي البسيط، مع تفريغ كل أسبوع رابع.',
  'Three days on the 5×5 routines, a little heavier every week, then a light week to bounce back.': 'ثلاثة أيام على روتينات 5×5، أثقل قليلًا كل أسبوع، ثم أسبوع خفيف لتستعيد نشاطك.',
  'Upper / lower by effort, 6 weeks': 'علوي / سفلي حسب المجهود، 6 أسابيع',
  'Use my current plan': 'استخدام خطتي الحالية',
  'Week 1 starts now. Have fun!': 'الأسبوع 1 يبدأ الآن. استمتع!',
