  "Add {0}?": "إضافة {0}؟",
  "Any blank NTAG sticker works. Writing replaces what was on it.": "أي ملصق NTAG فارغ يصلح. الكتابة تستبدل ما كان عليه.",
  "Hold the back of your phone to the sticker.": "قرّب ظهر هاتفك من الملصق.",
  "Hold the top of your iPhone near the sticker.": "قرّب أعلى iPhone من الملصق.",
  "It isn’t in this workout yet.": "ليس في هذا التمرين بعد.",
  "Just check in": "تسجيل الدخول فقط",
