  "NFC sticker for this exercise": "ملصق NFC لهذا التمرين",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "ضعه على خزانتك أو حقيبتك أو باب النادي. لمسة واحدة بهاتفك وتكون جاهزًا.",
  "Set up an NFC sticker": "إعداد ملصق NFC",
  "Shows your gym membership code, ready for the scanner.": "يعرض رمز عضويتك، جاهزًا للماسح.",
  "Start today’s workout": "ابدأ تمرين اليوم",
  "Starts what’s planned for today, or opens the one already running.": "يبدأ ما خُطّط لليوم، أو يفتح التمرين الجاري.",
  "Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.": "ضعه على الجهاز. المسه أثناء التمرين للانتقال إلى {0} أو لإضافته.",
  "Sticker ready.": "الملصق جاهز.",
  "Sticker ready. Tap it with your phone to try it.": "الملصق جاهز. المسه بهاتفك لتجربته.",
  "Tap it at the gym to start your workout or show your code.": "المسه في النادي لبدء تمرينك أو لعرض رمزك.",
  "That didn’t work. Hold your phone still on the sticker and try again.": "لم ينجح ذلك. أبقِ هاتفك ثابتًا على الملصق وحاول مرة أخرى.",
