  "This sticker is for an exercise you don’t have.": "هذا الملصق لتمرين ليس لديك.",
  "This sticker is locked. Try a blank one.": "هذا الملصق مقفل. جرّب ملصقًا فارغًا.",
  "This sticker is too small. NTAG213 or bigger works.": "هذا الملصق صغير جدًا. NTAG213 أو أكبر يصلح.",
  "When you tap it": "عند لمسه",
