  "For this workout": "لهذا التمرين",
  "Heavy lifts get more rungs, light ones one or none.": "الأوزان الثقيلة تحصل على درجات أكثر، والخفيفة على درجة أو لا شيء.",
  "It hurts": "يؤلمني",
