  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "هناك انزعاج، لذا وزن أخف لما تبقى. توقف إن استمر الألم.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "هناك انزعاج، لذا تنتقل المجموعات المتبقية إلى حركة تعمل على العضلة نفسها بزاوية ألطف.",
  "Keep these warm-ups": "احتفظ بهذا الإحماء",
  "Kept. Same warm-ups next time, scaled to your work weight.": "تم الحفظ. الإحماء نفسه في المرة القادمة، بحسب وزن العمل.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "المجموعات المسجّلة وروتينك تبقى كما هي. المدرب ليس طبيبًا ولا أخصائي علاج طبيعي. إذا آلمك شيء، استشر مختصًا.",
