  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "القرفصاء والضغط والسحب وأمثالها تحصل على تدرّج. تمارين الثني والرفع تبدأ مباشرة.",
  "Straight into the work sets.": "مباشرة إلى مجموعات العمل.",
  "That workout is over, so these can’t be applied any more.": "انتهى ذلك التمرين، لذا لم يعد بالإمكان تطبيقها.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "يتدرّج التطبيق من وزن العمل: إحماء أكثر عند الثقل وأقل عند الخفة، بأقراص صالتك.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "الحامل مشغول، لذا أجّله إلى النهاية. بقية الجلسة لا تحتاجه.",
  "There’s no workout running.": "لا يوجد تمرين جارٍ.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "يأتي هذا الإحماء قبل مجموعات العمل في كل جلسة كنسبة من وزن العمل، فيكبر معه.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "هذا عرض تجريبي، فلا يوجد نموذج ذكاء اصطناعي خلفي. على خادمك الخاص أقرأ جلستك وأقترح تغييرات كهذه.",
